const mensagensSocios = [];

const idLeitura = 'KM-' + agora.toFormat('ddMMyyHHmmss');

if (kmNovo != null) {
  kmAtual = kmNovo;
  kmAtualEm = hoje.toFormat('dd/MM/yyyy');
  log = { id_leitura: idLeitura, placa, km: String(kmNovo), data: kmAtualEm, origem: 'whatsapp', registrado_em: agora.toFormat('dd/MM/yyyy HH:mm') };
  let l = placa + ': ' + fmtKm(kmNovo) + ' registrado.';
  if (kmAnterior != null && kmNovo - kmAnterior > 8000) l += ' Atenção: +' + fmtKm(kmNovo - kmAnterior) + (dataAnterior ? ' desde ' + dataAnterior.toFormat('dd/MM') : '') + '.';
  linhasResp.push(l);
}

if (oleoKm != null) {
  kmOleo = oleoKm;
  dataOleo = (oleoData || hoje).toFormat('dd/MM/yyyy');
  avisoOleo = '';
  if (kmNovo == null) {
    log = { id_leitura: idLeitura, placa, km: String(oleoKm), data: dataOleo, origem: 'troca_oleo', registrado_em: agora.toFormat('dd/MM/yyyy HH:mm') };
    if (kmAtual == null) { kmAtual = oleoKm; kmAtualEm = dataOleo; }
  }
  linhasResp.push(placa + ': troca de óleo registrada (' + fmtKm(oleoKm) + ' em ' + dataOleo + ').');
}

// ---- aviso de troca de óleo
if (kmOleo != null && kmAtual != null) {
  const rodado = kmAtual - kmOleo;
  if (rodado >= INTERVALO_OLEO) {
    if (String(avisoOleo) !== String(kmOleo)) {
      mensagensSocios.push('TROCA DE ÓLEO: ' + placa + (nomeVeic ? ' (' + nomeVeic + ')' : '') + ' rodou ' + fmtKm(rodado) + ' desde a última troca (' + fmtKm(kmOleo) + (dataOleo ? ' em ' + dataOleo : '') + '). Km atual: ' + fmtKm(kmAtual) + '.');
      avisoOleo = String(kmOleo);
    }
    linhasResp.push('Óleo: ' + fmtKm(rodado) + ' desde a troca. Vencido.');
  } else {
    linhasResp.push('Óleo: faltam ' + fmtKm(INTERVALO_OLEO - rodado) + ' (troca em ' + fmtKm(kmOleo + INTERVALO_OLEO) + ').');
  }
} else if (kmNovo != null) {
  linhasResp.push('Sem troca de óleo registrada. Informe o km e a data da última troca.');
}

// ---- limite mensal de km da locação
if (kmNovo != null) {
  const bruto = String($('Agente Juninho').first().json.output || '');
  const locMarcada = (bruto.match(/\[\[KM:[^\]]*?\|[^|\]]*\|\s*(LOC-[\w-]+)/) || [])[1];
  const loc = locMarcada
    ? locacoes.find((l) => chave(l.id_locacao) === chave(locMarcada))
    : locacoes.find((l) => chave(l.placa) === chave(placa) && semAcento(l.status) === 'ativa');
  if (loc) {
    const LIMITE_KM = paraKm(loc.limite_km_mensal) || LIMITE_PADRAO;
    const VALOR_KM = paraNumero(loc.valor_km_excedente) != null ? paraNumero(loc.valor_km_excedente) : VALOR_PADRAO;
    const d0 = lerData(loc.data_inicio);
    const kmIni = paraKm(loc.km_inicio);
    if (!d0 || kmIni == null) {
      linhasResp.push('Locação ' + loc.id_locacao + ' sem km inicial: informe o km do veículo na entrega para controlar o limite de ' + fmtKm(LIMITE_KM) + '/mês.');
    } else {
      // leituras do veículo, incluindo o km da entrega e a leitura de hoje
      let pts = [{ d: d0, km: kmIni }];
      for (const r of leituras) {
        if (chave(r.placa) !== chave(placa)) continue;
        const d = lerData(r.data);
        const k = paraKm(r.km);
        if (d && k != null && d >= d0) pts.push({ d, km: k });
      }
      pts.push({ d: hoje, km: kmNovo });
      pts.sort((a, b) => a.d.toMillis() - b.d.toMillis() || a.km - b.km);
      // km nunca diminui: descarta leituras fora de ordem
      const ok = [];
      for (const p of pts) { if (!ok.length || p.km >= ok[ok.length - 1].km) ok.push(p); }
      pts = ok;
      const dataAnteriorLeitura = (() => {
        const ant = pts.filter((p) => p.d < hoje || (p.d.equals(hoje) && p.km < kmNovo));
        return ant.length ? ant[ant.length - 1].d : d0;
      })();
      let estimado = false;
      const kmEm = (data) => {
        if (data <= pts[0].d) return pts[0].km;
        const ult = pts[pts.length - 1];
        if (data >= ult.d) return ult.km;
        for (let i = 0; i < pts.length - 1; i++) {
          const a = pts[i], b = pts[i + 1];
          if (data >= a.d && data <= b.d) {
            if (data.equals(a.d)) return a.km;
            if (data.equals(b.d)) return b.km;
            estimado = true;
            const span = b.d.diff(a.d, 'days').days || 1;
            return a.km + (b.km - a.km) * (data.diff(a.d, 'days').days / span);
          }
        }
        return ult.km;
      };
      let kAtual = 0;
      while (d0.plus({ months: kAtual + 1 }) <= hoje) kAtual++;
      const periodos = [];
      for (let k = 0; k <= kAtual; k++) {
        const ini = d0.plus({ months: k });
        const fim = d0.plus({ months: k + 1 });
        const encerrado = k < kAtual;
        if (encerrado && !(fim > dataAnteriorLeitura && fim <= hoje)) continue; // já informado antes
        estimado = false;
        const kIni = kmEm(ini);
        const kFim = encerrado ? kmEm(fim) : kmNovo;
        const uso = kFim - kIni;
        const exc = Math.max(0, Math.round(uso - LIMITE_KM));
        if (exc > 0) periodos.push({ ini, fim, encerrado, uso: Math.round(uso), exc, valor: exc * VALOR_KM, estimado });
      }
      if (periodos.length) {
        const cab = 'LIMITE DE KM ATINGIDO: ' + (loc.cliente_nome || 'cliente') + ' (' + placa + '), limite de ' + fmtKm(LIMITE_KM) + '/mês.';
        const linhas = periodos.map((p) =>
          '- ' + p.ini.toFormat('dd/MM') + ' a ' + p.fim.minus({ days: 1 }).toFormat('dd/MM') + (p.encerrado ? ' (encerrado)' : ' (em andamento, até hoje)') +
          ': rodou ' + fmtKm(p.uso) + ', excedente ' + fmtKm(p.exc) + ' x ' + brl(VALOR_KM) + ' = ' + brl(p.valor) + (p.estimado ? ' (estimado)' : ''));
        const total = periodos.reduce((s, p) => s + p.valor, 0);
        mensagensSocios.push([cab].concat(linhas).concat(periodos.length > 1 ? ['Total a cobrar: ' + brl(total)] : []).join('\n'));
        linhasResp.push('Limite de km excedido (' + brl(total) + ').');
      }
    }
  }
}

const mensagens = [respostaPara(linhasResp.join(' '))];
if (mensagensSocios.length) mensagens[0].resposta += ' Sócios avisados.';
for (const texto of mensagensSocios) {
  for (const dest of SOCIOS) mensagens.push({ chatId: dest, sessao: prep.sessao, resposta: '[Juninho] ' + texto });
}

const veiculoOut = {
  placa: String(veic.placa),
  km_atual: kmAtual == null ? '' : String(kmAtual),
  km_atualizado_em: kmAtualEm,
  km_ultima_troca_oleo: kmOleo == null ? '' : String(kmOleo),
  data_ultima_troca_oleo: dataOleo,
  km_aviso_oleo: String(avisoOleo),
};
return saida({ gravar: true, log, veiculo: veiculoOut, mensagens });

const prep = $('Preparar Resposta').first().json;
const texto = String(prep.resposta || '').replace(/^\[Juninho\]\s*/, '').trim();
const msgs = ($('Montar km').first().json.mensagens || []).map((m) => ({ ...m }));
if (texto && msgs.length) {
  msgs[0].resposta = '[Juninho] ' + texto + '\n' + String(msgs[0].resposta || '').replace(/^\[Juninho\]\s*/, '');
}
return msgs.map((m) => ({ json: m }));

const bruto = String($('Agente Juninho').first().json.output || '');
const m = bruto.match(/\[\[ARQUIVAR:\s*([^|\]]*)\|?\s*([^\]]*)\]\]/);
const limpo = (s) => String(s || '').replace(/[\\/:*?"<>|]/g, ' ').replace(/\s+/g, ' ').trim();
const cliente = limpo(m && m[1]) || 'cliente';
const tipo = limpo(m && m[2]) || 'documento';
const media = $('Entrada WhatsApp (WAHA)').first().json.body.payload.media || {};
let bin = null;
for (const n of ['Baixar imagem (WAHA)', 'Baixar documento (WAHA)']) {
  try {
    const it = $(n).first();
    if (it && it.binary && it.binary.data) { bin = it.binary.data; break; }
  } catch (e) {}
}
if (!bin) return [];
const mime = String(media.mimetype || bin.mimeType || '').toLowerCase();
const mapa = { 'image/jpeg': 'jpg', 'image/png': 'png', 'image/webp': 'webp', 'image/heic': 'heic', 'application/pdf': 'pdf', 'application/msword': 'doc', 'application/vnd.openxmlformats-officedocument.wordprocessingml.document': 'docx' };
const doNome = (String(media.filename || '').match(/\.([A-Za-z0-9]{2,5})$/) || [])[1];
const ext = (doNome || mapa[mime.split(';')[0]] || 'bin').toLowerCase();
const data = $now.setZone('America/Sao_Paulo').toFormat('dd-MM-yyyy HHmm');
const arquivoNome = cliente + ' - ' + tipo + ' - ' + data + '.' + ext;
return [{ json: { arquivoNome, cliente, tipo }, binary: { data: bin } }];

const base = $('Montar arquivo').first();
const pastaId = ($json.files && $json.files[0] && $json.files[0].id) || $json.id;
return [{ json: { pastaId, arquivoNome: base.json.arquivoNome }, binary: base.binary }];
